#!/usr/bin/env python3
"""
Round 166p (culprits), 4 October 2026. Needs round 165b.

Streets and places: a View box tick that shows or hides everything an
OpenStreetMap map shows (roads, buildings, rivers, land use, shops, schools
and other places), like Place names. Adds OpenStreetMap's points of interest.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 166p (4 October)\n\nNeeds round 165b (the Woodlands names; guards on its heading). No tiles\npatch. No app.js?v= bump. Named "p" so it cannot clash with the other chats\'\nnumbers.\n\n- Asked 4 October: a box like Place names that shows or hides the places,\n  anything an OpenStreetMap map would show. New tick "Streets and places"\n  under Place names in the View box (details-toggle, DETAILS_ON, setDetails,\n  localStorage culprits-details), on by default.\n- It hides or shows, on every basemap, each basemap layer drawn from\n  OpenStreetMap\'s roads and railways, road names, buildings (and the 3D\n  buildings), land use, rivers and their names, airports, parks, town marks,\n  house numbers and points of interest (DETAIL_PARTS). The land and sea\n  (water, land cover) always stay; place names stay with the Place names box.\n  Layers are hidden by narrowing their zooms to 24-24 and put back to their\n  own (detailsZoom), so setBasemap\'s visibility switching is untouched;\n  basemaps added later are caught on styledata.\n- No basemap drew OpenStreetMap\'s points of interest, so they are added:\n  outline-places-dot (from zoom 14, every kind the tiles carry, coloured by\n  kind in teal to cobalt, OSM_PLACE_KINDS) and outline-places-name (Jost, from\n  zoom 15.5), source "osm". Named as basemap layers so the colour wheel and\n  remap leave them alone; hudEligible skips them (no glow). Kept just over the\n  basemap stack and under the data (osmPlacesBefore, osmPlacesPlace); hidden\n  while the hologram is on.\n- Checked in Chromium (MapLibre 5.24): box shows, roads hidden and the sea\n  kept on Country outlines, Deep space and Woodlands, back at their own zooms\n  when ticked, places sit above the basemap stack. OpenFreeMap is blocked from\n  the sandbox, so the places themselves were not seen drawn.\n']

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round166p: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 165b" not in h.read_text(encoding="utf-8"):
        sys.exit("round166p: round 165b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round166p: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round166p: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round166p: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
